// And groups predicates with the AND operator between them.
func And(predicates ...predicate.WorkResponsibility) predicate.WorkResponsibility {
	return predicate.WorkResponsibility(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.WorkResponsibility) predicate.WorkResponsibility {
	return predicate.WorkResponsibility(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.WorkResponsibility) predicate.WorkResponsibility {
	return predicate.WorkResponsibility(sql.NotPredicates(p))
}
